"""Independent assessment of uploaded scalar evidence; no full-field replay."""
import argparse,csv,hashlib,html,io,json
from pathlib import Path
from datetime import datetime,timezone
from zoneinfo import ZoneInfo
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

p=argparse.ArgumentParser(description=__doc__);p.add_argument('--evidence-dir',type=Path,required=True);p.add_argument('--archive',type=Path,required=True);p.add_argument('--output',type=Path,required=True);args=p.parse_args()
ROOT=args.evidence_dir.resolve()
OUT=args.output.resolve();OUT.mkdir(parents=True,exist_ok=True)
audit_path=ROOT/'independent-audit.json'
if not audit_path.exists():audit_path=Path(__file__).resolve().parent/'independent-audit.json'
assert hashlib.sha256(args.archive.read_bytes()).hexdigest()==json.loads(audit_path.read_text())['archive_sha256'],'Archive differs from assessed input'
r=json.loads((ROOT/'record.json').read_text());cases={f.stem:json.loads(f.read_text()) for f in (ROOT/'cases').glob('*.json')}
now=datetime.now(timezone.utc);stamp={'utc':now.isoformat(),'melbourne':now.astimezone(ZoneInfo('Australia/Melbourne')).isoformat()}

def prediction(m,x):
 z=(np.asarray(x)-m['origin'])/m['scale'];c=m['coefficients']
 return np.exp(c[0]+c[1]*z) if m['model']=='exponential' else np.polynomial.polynomial.polyval(z,c)

summary=[]
for b in r['blocks']:
 m=b['models'][0];summary.append({'block':b['id'],'adaptive_used':len(b['development'])-4,'adaptive_limit':9 if b['field']=='hopfion' else 6,'model':m['model'],'validation_rmse_fraction':m['validation_rmse'],'validation_max_percentage_points':100*m['validation_max_abs_error'],'refinement_stop':b['stop_reason'],'validation_pass':b['empirical_prediction_check']})

late={k:sorted([c for c in cases.values() if c['parameters']['field']==k and c['parameters']['duration']==1 and c['parameters']['rotation_code'] is None],key=lambda c:c['parameters']['steps']) for k in ['hopfion','packet']}
fig,axes=plt.subplots(2,2,figsize=(12,9),layout='constrained');colors={'hopfion':'#275e8c','packet':'#bd6106'}
for kind in ['hopfion','packet']:
 b=next(v for v in r['blocks'] if v['id']==kind+'-duration');dev=b['development'];val=b['validation'];x=np.linspace(.2,1,200)
 axes[0,0].plot(x,100*prediction(b['models'][0],x),color=colors[kind],label=kind.title())
 axes[0,0].scatter([v['x'] for v in dev],[100*v['y'] for v in dev],s=15,color=colors[kind]);axes[0,0].scatter([v['x'] for v in val],[100*v['y'] for v in val],s=30,marker='s',color=colors[kind])
 a=late[kind];dt=[v['dt'] for v in a];base=a[0]['sync_native_error'];change=[100*(v['sync_native_error']/base-1) for v in a]
 axes[0,1].plot(dt,change,'o-',color=colors[kind],label=kind.title())
 residual=[100*abs(v['poynting_balance']['defect_over_initial_energy']) for v in a]
 gap=[100*abs(v['coarser_flux_quadrature']['integrated_flux']-v['poynting_balance']['integrated_flux'])/v['trace'][0]['energy'] for v in a]
 axes[1,0].plot(dt,residual,'o-',color=colors[kind],label=kind.title()+' balance defect');axes[1,0].plot(dt,gap,'s--',color=colors[kind],label=kind.title()+' flux quadrature gap')
axes[0,0].set(title='Duration dependence: accurate fits to numerical errors',xlabel='T (model units)',ylabel='Synchronized native field L2 (%)',yscale='log');axes[0,0].legend();axes[0,0].text(.98,.04,'Squares: withheld validation',ha='right',transform=axes[0,0].transAxes,fontsize=9)
axes[0,1].set(title='T=1: fourfold smaller dt barely changes total error',xlabel='dt (model units; log scale)',ylabel='Relative change of total error (%)',xscale='log');axes[0,1].legend()
axes[1,0].set(title='Flux-time refinement leaves a balance-defect floor',xlabel='dt (model units; log scale)',ylabel='Magnitude / initial cube energy (%)',xscale='log',yscale='log');axes[1,0].legend(fontsize=8)
b=next(v for v in r['blocks'] if v['id']=='hopfion-duration');m=b['models'][0];x=np.linspace(.48,.66,200);c=m['coefficients'];curv=100*(2*c[2]+6*c[3]*(x-m['origin'])/m['scale'])/m['scale']**2
axes[1,1].plot(x,curv,color=colors['hopfion'],label='Second derivative of fitted cubic');axes[1,1].axhline(0,color='#777',lw=.8);axes[1,1].axvspan(.5625,.5916666666666667,color='#e6a34a',alpha=.2,label='Current local curvature-sign bracket');axes[1,1].set(title='Focus extra duration samples near the curvature change',xlabel='T (model units)',ylabel='Fitted curvature (percentage points / T²)');axes[1,1].legend(fontsize=8);axes[1,1].text(.04,.04,'Fit-derived diagnostic; inflection location remains provisional',transform=axes[1,1].transAxes,fontsize=8)
for ax in axes.flat:ax.grid(alpha=.2)
fig.suptitle('Workstation bounded Maxwell run — independent compact-evidence review',fontsize=14);fig.savefig(OUT/'assessment-curves.png',dpi=300);buf=io.StringIO();fig.savefig(buf,format='svg');svg=buf.getvalue();svg=svg[svg.index('<svg'):];plt.close(fig)

table=''.join(f"<tr><td>{v['block']}</td><td>{v['adaptive_used']}/{v['adaptive_limit']}</td><td>{v['model']}</td><td>{v['validation_max_percentage_points']:.6g}</td><td>{v['refinement_stop']}</td></tr>" for v in summary)
timing=(datetime.fromisoformat(r['finished_at']['utc'])-datetime.fromisoformat(r['recorded_at']['utc'])).total_seconds()
bytes_fields=sum(v['bytes'] for v in json.loads((ROOT/'field-manifest.json').read_text())['files'])
data={'assessment_recorded_at':stamp,'source_archive':'evidence(20261113-223432).zip','source_archive_sha256':hashlib.sha256(args.archive.read_bytes()).hexdigest(),'run_started':r['recorded_at'],'run_finished':r['finished_at'],'compute_seconds':timing,'completed_cases':61,'field_counts':{'hopfion':36,'packet':25},'compact_integrity':{'CRC':'all 129 ZIP entries read without CRC error','root_hashed_members':128,'mismatches':0,'missing':0,'nested_package_hashed_members':19},'fit_summary':summary,'late_time_diagnostics':{k:[{v:c[v] for v in ['parameters','dt','E_error','B_synchronized_error','sync_native_error','collocated_error','initial_discrete_divergence_normalized','max_discrete_divergence_change_normalized','poynting_balance','coarser_flux_quadrature','modified_energy_relative_drift','physical_energy_relative_change']} for c in cs] for k,cs in late.items()},'full_fields_scope':{'manifest_count':61,'declared_bytes':bytes_fields,'manifest_to_case_receipts_crosschecked':True,'full_arrays_supplied':False,'independent_NPZ_CRC_or_metric_replay':False},'disposition':'Bounded numerical-control extension completed; five held-out prediction checks passed; Hopfion-duration refinement criterion remains open. No full-grid/domain or physical-model admission.'}
(OUT/'assessment.json').write_text(json.dumps(data,indent=2)+'\n')
if (OUT/'independent-audit.json').resolve()!=audit_path.resolve():(OUT/'independent-audit.json').write_bytes(audit_path.read_bytes())
with (OUT/'fit-summary.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(summary[0]),lineterminator='\n');w.writeheader();w.writerows(summary)

text=f'''<h1>Bounded Maxwell validation: assessment and next steps</h1><p><strong>Disposition:</strong> the finite 65³ numerical-control run completed, and all five frozen models passed their withheld prediction check. Hopfion-duration refinement remains open because its feature bracket missed the declared stopping tolerance. These results characterize numerical behaviour; no physical-model or SF motion gate is closed.</p><p>Assessment UTC: {html.escape(stamp['utc'])}; Melbourne: {html.escape(stamp['melbourne'])}. Run: {html.escape(json.dumps(r['recorded_at']))} to {html.escape(json.dumps(r['finished_at']))}. Computation: {timing:.2f} seconds (about 8 min 49 s), followed by export/field checks. Source commit: {r['environment']['source_commit']}.</p><h2>Integrity and scope</h2><p>The uploaded ZIP has 129 entries, no CRC errors and 128/128 valid top-level payload hashes. All 19 nested package hashes also match. Source, configuration and declared field hashes are consistent with the receipts. There are 61 unique cases: 36 Hopfion and 25 periodic packet cases. The 80-case bound is a maximum; early stopping and reuse of identical configurations reduced the total. Manufactured qualification and all 25 periodic case-control groups passed.</p><p>The 61 local float64 field files are declared at {bytes_fields:,} bytes ({bytes_fields/1024**3:.3f} GiB), but are absent from this compact ZIP. Their declarations were cross-checked against the case receipts; their bytes, NPZ CRCs and full-field metrics have not been independently replayed in this assessment. The included read-only workstation verifier can check the retained files before archival. Preserve the original archive and local fields.</p>{svg}<h2>Fits and adaptive sampling</h2><table><tr><th>Block</th><th>Adaptive used/allowed</th><th>Frozen primary model</th><th>Max withheld error (percentage points)</th><th>Refinement stop</th></tr>{table}</table><p>All withheld maxima are below the predeclared 0.0005 percentage-point prediction tolerance (5e-6 as a fraction). This tolerance concerns the prediction of numerical error, not an acceptance threshold for the field solution itself. Cubics beat line/exponential models for the nonconstant responses in this run. The angle response is constant at the acquisition floor. All model choices were frozen before their block validation measurements; the validation levels are disjoint from development levels and recorded adaptive selections precede their measurements. Validation residuals and all 61 recorded Poynting defects were independently recomputed from the compact numbers.</p><p>Hopfion duration used all nine adaptive additions. Its last premeasurement prediction residual was 1.4915e-8, within the 1e-6 sequential tolerance, but its tracked feature bracket is 0.036458 of the full T span (3.646%), above the 3% goal. The remaining gap is feature localization, not a failed withheld prediction. A global cubic suggests an inflection around T=0.5602; adjacent divided-difference curvatures change sign in the vicinity of T=0.5625–0.5917. Nonuniform divided differences are approximate curvature locations, so neither is an exact inflection certificate. Add a small number of localized measurements rather than repeating a broad sweep.</p><h2>What the measurements show</h2><p>At fixed dt=1/240, Hopfion synchronized native field error grows from 0.394673% at T=0.2 to 0.975997% at T=0.5 and 1.945625% at T=1. The packet grows from 0.0199624% to 0.0496548% and 0.0985835%. The observed duration dependence is close to linear with a small, resolved curvature; an exponential is a poorer empirical description over this tested range. No extrapolation to long-time physical instability is justified.</p><p>At T=1, reducing dt from 1/240 to 1/960 changes the Hopfion error from 1.945625% to 1.947248%, and packet error from 0.0985835% to 0.0986776%. Total errors change by only about 0.08–0.10% relative and slightly increase. Time refinement alone is therefore unlikely to remove the dominant error at this grid. A spatial/discrete-initialization/observation contribution is a leading hypothesis, not a demonstrated decomposition. Do not select the largest dt just because cancellation gives it a slightly lower total norm.</p><p>The Fourier packet reference agrees with its exact finite-mode field at roughly 6e-16. At T=1 its common-grid difference from Yee is about 0.19218%, while Yee's synchronized native error is about 0.09858%. These are different observables: the common-grid result includes the linear interpolation used to combine staggered components. Keep those responses separate when comparing future curves.</p><p>Initial normalized discrete divergence is about 0.03350 for Hopfion and 0.002065 for the packet. Its subsequent change is at most about 1.36e-13. The scheme preserves an initially nonzero discrete residual; it does not establish zero discrete divergence. This is not an emergent charge observation. The periodic modified-energy invariant drifts by at most 2.22e-16, while synchronized collocated physical-energy change is about 1.73e-7 at most. A discrete invariant and physical energy are distinct diagnostics.</p><p>The flux quadrature gaps decrease by approximately a factor of four for each halving of dt, but the balance defects approach nonzero values. At T=1 and dt=1/960, Hopfion defect magnitude is about 0.03028% of initial cube energy, or 1.137% of the transported-energy normalization. Packet values are 0.05752% and 1.865%. That combination points toward remaining spatial/observation balance error, rather than a flux-time quadrature problem alone. It is not an isolated outer-boundary conservation certificate.</p><p>The chosen Hopfion y-axis sweep shows no resolved dependence in its aggregate field-error response: the observed spread is about 1e-17 in fractional error. Packet cubic rotations agree to rounding scale. These narrow results do not establish arbitrary-angle isotropy for other fields, local directional diagnostics or boundaries. No further angle budget is warranted for this same aggregate response.</p><h2>Sampler correction before another handover</h2><p>The manufactured x³ inflection control passes, but the saved qualification also labels two roots around ±1.05e-8 as turning points. Those are numerical splits of a stationary-inflection root; slope reversal was not required by the root-based classifier. Before further feature-driven runs, require a derivative sign change across a candidate extremum, merge near-coincident roots, and keep inflection/turning-point labels separate. No recorded field errors or fit-validation outcomes are invalidated by this label issue.</p><h2>Recommended ordered next steps</h2><ol><li><strong>Preserve and record this tranche.</strong> Verify the retained 61 states, archive using the established local-workstation upload/download-verification procedure, and publish an immutable assessment with the Hopfion refinement qualification retained. All GitHub activity remains on the workstation. Do not overwrite earlier reports or delete full fields before verified archival.</li><li><strong>Close the small duration-localization gap.</strong> After correcting feature labels, allow roughly 2–3 additional sequential points concentrated near T≈0.56–0.59, with N=65, L=8, dt=1/240, phase/orientation/startup/boundary prescription unchanged. Reserve new validation values before adaptation. Older withheld points have now been reviewed and are not fresh validation for an updated model. If the bracket criterion still cannot be met, record unresolved rather than changing the tolerance.</li><li><strong>Make spacing the next main independent variable.</strong> Start a fixed-box h study for both matched controls at T=1, phase=0 and fixed dt=1/960. Use a bounded odd-grid candidate range such as N=49–129, a small seed spread, adaptive additions and reserved validation grids. Keep the physical observation region and quadrature coordinates fixed across meshes; independently quantify interpolation/observation error, while retaining native-grid errors. Test a physically motivated a+b*h^p relationship alongside simple empirical alternatives. A reduced error plus validated response is needed before choosing an operating grid. The existing data do not yet establish a spatial order.</li><li><strong>Check the remaining floor only after the spacing curve.</strong> At coarse and fine anchors, use a separately held-grid time-step check to verify that dt=1/960 remains subordinate. If mesh refinement does not explain the residual, isolate one startup convention or one boundary/domain control at a time. A domain study must hold h fixed, with node count derived from domain size, and use the same physical measurement region. Do not silently project away divergence or compare differently modified initial fields as if they were identical.</li><li><strong>Return the qualified methods to the main research track.</strong> Apply the verified observation, constraint and one-variable convergence practices to Q2 reference and Q3 SF motion/initialization controls. A Maxwell propagator cannot validate a different SF field equation by substitution. Keep Q1 parked and Q4/Q7 unresolved findings intact; defer broader topology/model sweeps until these numerical controls are settled. No confinement, electric charge, quantum spin or electron conclusion follows from these curves.</li></ol><p>The next operating-point decision needs a declared numerical field-error budget and cost objective, independent of the existing SF speed gate. No optimum or acceptable mesh has been established here. This deliverable is an assessment and proposed scope; it does not launch a new campaign or alter GitHub.</p>'''
(OUT/'ASSESSMENT.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bounded Maxwell evidence assessment</title><style>body{font:16px/1.65 system-ui;max-width:1250px;margin:30px auto;padding:0 20px;color:#18324a}h1,h2{line-height:1.25}svg{width:100%;height:auto}table{border-collapse:collapse;font-size:14px}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:left}li{margin-bottom:14px}</style>'+text+'</html>')
print(OUT)
